head.script:

scwin._checkRow = function() {
	let tr = WebSquare.wUnit.getJq("#wq_uuid_3_body_tbody tr").not(".w2grid_hidedRow");
    return tr.length == 4;
}
scwin.clickCheckbox = function() {
    if(WebSquare.wUnit.getObjById("wq_uuid_3_cell_1_0").childNodes[0].getAttribute("disabled") == null){
        WebSquare.wUnit.getObjById("wq_uuid_3_cell_1_0").childNodes[0].click();
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 개발자도구 (F12) 를 실행한다.
    //1. Run the Developer Tool (F12) in your browser.
    //Test step 2. 콘솔탭에서 WebSquare.layer.showModal([]) 를 입력한다.
    //2. On the Console tab, type WebSquare.layer.showModal ([]).
    WebSquare.wUnit.addCommand("set", "WebSquare.layer.showModal([])");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. showModal 이 된다.
    //2. Become showModal.
    WebSquare.wUnit.addCommand("assert", "_modal.style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    //Test 3. dataList1.insertRow() 를 입력한다.
    //3. Type dataList1.insertRow ().
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('dataList1').insertRow()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. Row 가 추가된다.
    //3. Row is added.
    WebSquare.wUnit.addCommand("set", "scwin._checkRow()");
    WebSquare.wUnit.addCommand("pause", "500");

    //Test step 4. WebSquare.layer.hideModal() 를 입력한다.
    //4. Enter WebSquare.layer.hideModal ().
    WebSquare.wUnit.addCommand("set", " WebSquare.layer.hideModal()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. hideModal 이 된다.
    //4. Become a hideModal.
    WebSquare.wUnit.addCommand("assert", "_modal.style.display == 'none'", "true");

    //Test step 5. 임의의 체크박스를 클릭한다.
    //5. Click any checkbox.
    WebSquare.wUnit.addCommand("set", "scwin.clickCheckbox()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 정상적으로 체크박스가 동작한다. (그전버전에서는 CheckBox 가 Disabled 되서 체크하지 못했음.)
    //5. Check box works normally. (In previous versions, the CheckBox was disabled and could not be checked.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_1_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    WebSquare.layer.showModal([]);
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    WebSquare.layer.hideModal();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Feb-2018
    //End unitTest
}
